scripts.list:
// GET / and GET /?show=open|done
function handle(req) {
  // Booleans are stored as 0 or 1.
  let where = '';
  if (req.query.show === 'open') where = ' WHERE done = 0';
  if (req.query.show === 'done') where = ' WHERE done = 1';
  const tasks = db.query('SELECT id, title, done FROM tasks' + where + ' ORDER BY id DESC');
  // Alias aggregates: the key is the alias, the value a number.
  const counts = db.query('SELECT SUM(done = 0) AS open, SUM(done = 1) AS closed FROM tasks')[0];
  return {template: 'list', data: {tasks: tasks, open: counts.open || 0, closed: counts.closed || 0}};
}

scripts.create:
// POST /tasks  form: title
function handle(req) {
  const title = (req.form.title || '').trim();  // form values are strings
  if (!title) return {text: 'title is required', status: 400};
  db.exec('INSERT INTO tasks (title, done) VALUES (?, 0)', title);
  return {redirect: '/'};
}

scripts.edit_form:
// GET /tasks/:id
function handle(req) {
  const rows = db.query('SELECT id, title, done FROM tasks WHERE id = ?', Number(req.params.id));
  if (rows.length === 0) return {template: 'not_found', status: 404};
  return {template: 'edit', data: {task: rows[0]}};
}

scripts.update:
// POST /tasks/:id  form: title, done (checkbox: present as '1' when checked, absent otherwise)
function handle(req) {
  const title = (req.form.title || '').trim();
  if (!title) return {text: 'title is required', status: 400};
  const done = req.form.done === '1' ? 1 : 0;
  const r = db.exec('UPDATE tasks SET title = ?, done = ? WHERE id = ?', title, done, Number(req.params.id));
  if (r.rowsAffected === 0) return {template: 'not_found', status: 404};
  return {redirect: '/'};
}

scripts.toggle:
// POST /tasks/:id/toggle
function handle(req) {
  const r = db.exec('UPDATE tasks SET done = 1 - done WHERE id = ?', Number(req.params.id));
  if (r.rowsAffected === 0) return {template: 'not_found', status: 404};
  return {redirect: '/'};
}

scripts.delete:
// POST /tasks/:id/delete
function handle(req) {
  db.exec('DELETE FROM tasks WHERE id = ?', Number(req.params.id));
  return {redirect: '/'};
}

scripts.api:
// GET /api/tasks returns JSON for browser JavaScript
function handle(req) {
  return {json: db.query('SELECT id, title, done FROM tasks ORDER BY id')};
}
